import fs from 'node:fs';
import * as gates from '/home/vantt/projects/forgentX-phase00-documentation-authority-unification/scripts/check-doc-inventory-gates.mjs';
const root='/home/vantt/projects/forgentX-phase00-documentation-authority-unification',plan='plans/260925-documentation-authority-unification';
const old=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/closure-fixes-verification.json','utf8'));
const scope=[];for(let i=0;i<old.gates[2].command.length;i++)if(old.gates[2].command[i]==='--scope')scope.push(old.gates[2].command[i+1]);
const inventory=gates.loadInventory('/tmp/phase06/review-doc-inventory.json',{});delete inventory.consumerEdges;delete inventory.inboundEdges;for(const item of inventory.items){delete item.consumerEdgeIds;delete item.consumers;}if(global.gc)global.gc();
const registry=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/working-identity-registry.json','utf8'));
const vocabulary=JSON.parse(fs.readFileSync(root+'/'+plan+'/claim-and-disposition-vocabulary.json','utf8'));
const shards=[...gates.loadDecisionShards(root+'/'+plan+'/pilot/decisions'),...gates.loadDecisionShards(root+'/'+plan+'/ledger/decisions')];
const merged=gates.applyDecisions(inventory,shards,{vocabulary,registry,repoRoot:root,unitsOf:gates.buildConservationUnitLookup(root,inventory.commit),targetAnchorsOf:gates.buildTargetAnchorLookup(root,inventory.commit),targetUnitDigestOf:gates.buildTargetUnitDigestLookup(root,inventory.commit)});
const bindings=JSON.parse(fs.readFileSync('/tmp/phase06/a30-binding-associations.json','utf8'));
const projections=new Map();for(const b of bindings){const key=b.originalAuthorSession;if(!projections.has(key))projections.set(key,{version:1,shard:'receipt-binding-projection-'+projections.size,authorSession:key,sources:[],claims:[],candidateClassifications:[]});projections.get(key).candidateClassifications.push({...b.originalReference,claimId:b.currentClaimId});}
const before=gates.unreferencedCandidateRows(merged.inventory,shards,{scope,repoRoot:root});
const after=gates.unreferencedCandidateRows(merged.inventory,[...shards,...projections.values()],{scope,repoRoot:root});
const key=r=>[r.claimId,r.path,r.anchor,r.unitDigest].join('\0'),beforeKeys=new Set(before.map(key)),afterKeys=new Set(after.map(key));
const list=JSON.parse(fs.readFileSync(root+'/'+plan+'/reports/phase-06/candidate-unverified-agent-coordination.json','utf8')).rows;
const loc=r=>[r.path,r.anchor,r.unitDigest].join('\0'),listed=new Set(list.map(loc)),actual=new Set(after.map(loc));
const result={inventoryCommit:inventory.commit,attemptedBindings:bindings.length,beforeCount:before.length,afterCount:after.length,newlyClosed:before.filter(r=>!afterKeys.has(key(r))),newlyOpen:after.filter(r=>!beforeKeys.has(key(r))),listedMissing:list.filter(r=>!actual.has(loc(r))),additionalReverseUnits:after.filter(r=>!listed.has(loc(r))),holds:merged.inventory.claimLedger.filter(r=>gates.pathInScope(r.sourcePath,scope)&&r.reviewStatus!=='reviewed').map(r=>r.claimId).sort(),unsupportedIdentityPairs:bindings.filter(b=>b.currentClaimId!==b.receiptRowClaimId).length};
fs.writeFileSync('/tmp/phase06/a30-native-binding-proof.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({attempted:result.attemptedBindings,before:result.beforeCount,after:result.afterCount,newlyClosed:result.newlyClosed.length,listedMissing:result.listedMissing.length,additional:result.additionalReverseUnits.length,unsupportedIdentityPairs:result.unsupportedIdentityPairs}));
